            aOrbiterC = ((aWandererA + RotL64(aIngress, 34U)) + 0x6E907ACDF5FA7B73ULL) + aOASaltA[((aIndex + 109U)) & S_SALT1];
            aOrbiterF = ((aWandererJ + RotL64(aPrevious, 41U)) + 0x736C7B742DE0492EULL) + aOASaltE[((aIndex + 191U)) & S_SALT1];
            aOrbiterA = (aWandererB + RotL64(aScatter, 19U)) + 0x873F664D1C39082CULL;
            aOrbiterH = ((aWandererF + RotL64(aIngress, 27U)) + 0xC0BB5182F10A7955ULL) + aOASaltB[((aIndex + 85U)) & S_SALT1];
