            aOrbiterE = (aWandererF + RotL64(aScatter, 13U)) + 0xDEE228DFB889022CULL;
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 34U)) + 0xC85CC5B9F5718776ULL) + aOASaltB[(((511U - aIndex) + 389U)) & S_SALT1];
