            aOrbiterK = (((aWandererJ + RotL64(aCross, 47U)) + RotL64(aCarry, 23U)) + 0x86D70E2ECBEB7EBDULL) + aOASaltC[(((511U - aIndex) + 420U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 11U)) + 0xBA63CE48B2715FB7ULL) + aOASaltE[(((511U - aIndex) + 148U)) & S_SALT1];
            aOrbiterE = (((aWandererA + RotL64(aScatter, 23U)) + RotL64(aCarry, 41U)) + 0x81FAC68B2D1BA4BBULL) + aOASaltF[((aIndex + 85U)) & S_SALT1];
            aOrbiterC = (((aWandererG + RotL64(aIngress, 30U)) + RotL64(aCarry, 5U)) + 0xC598A117C083EBB4ULL) + aOASaltG[(((511U - aIndex) + 179U)) & S_SALT1];
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 57U)) + 0xC68B99EA57286F63ULL) + aOASaltH[((aIndex + 317U)) & S_SALT1];
