            aIngress ^= (RotL64(aEarthLaneC[((aIndex + 8459U)) & S_BLOCK1], 35U) ^ RotL64(aIceLaneD[((S_BLOCK1 - aIndex + 11588U)) & S_BLOCK1], 43U));
