            aOrbiterF = (aWandererH + RotL64(aPrevious, 21U)) + 0x6B950611B5B5B36EULL;
            aOrbiterA = (((aWandererG + RotL64(aScatter, 60U)) + RotL64(aCarry, 29U)) + 0x7F1444F2CAB2A71EULL) + aOASaltG[(((511U - aIndex) + 451U)) & S_SALT1];
