            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x75E77BABC679BA30ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xFA7F440428D7B536ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8157F4AF20E6586FULL), 5U);
