            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xA7AD877ACD2BD77CULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x5FBE4CC7B2282C95ULL) ^ aOUSaltG[((aIndex + 105U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xD4B26D45CBF8A37DULL), 13U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xF2AC4920687A37EEULL) + aOUSaltB[((aIndex + 363U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xFADC4BEA0B067BCCULL;
            aOrbiterE = RotL64((aOrbiterE * 0x318ABD254693E2F3ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xF44AB70F94324DD8ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xDCDB4D23A307430AULL;
