            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x63326AA965C543CAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x0B5728507F4DD887ULL), 23U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterE, 23U);
