            //
            aOrbiterK = ((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 41U)) + 0xF8AA52D4484378A1ULL;
            aOrbiterE = (aWandererB + RotL64(aCross, 60U)) + 0x40BB99307C21AD7AULL;
            aOrbiterJ = (((aWandererH + RotL64(aScatter, 27U)) + RotL64(aCarry, 3U)) + 0xAF6E7237F40E11DAULL) + aOASaltC[(((511U - aIndex) + 79U)) & S_SALT1];
            aOrbiterA = ((aWandererJ + RotL64(aPrevious, 47U)) + 0x360421D5412C795AULL) + aOASaltE[(((511U - aIndex) + 87U)) & S_SALT1];
